def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    separators = set()
    for r in sep_rows:
        separators.add(grid[r][0])
    for c in sep_cols:
        separators.add(grid[0][c])

    from collections import Counter
    counts = Counter(v for row in grid for v in row if v not in separators)
    background = counts.most_common(1)[0][0]

    rb = [-1] + sep_rows + [h]
    cb = [-1] + sep_cols + [w]
    out = []
    for i in range(len(rb) - 1):
        row = []
        for j in range(len(cb) - 1):
            marks = sum(
                grid[r][c] != background and grid[r][c] not in separators
                for r in range(rb[i] + 1, rb[i + 1])
                for c in range(cb[j] + 1, cb[j + 1])
            )
            row.append(1 if marks >= 2 else background)
        out.append(row)
    return out
